      simbol: [['"BC"', 'ketidaksamaan, 0 sama persis dan 1 tidak ada jenis bersama'], ['W', 'jumlah dari nilai terkecil tiap jenis di kedua komunitas'], ['N_1', 'jumlah individu komunitas pertama'], ['N_2', 'jumlah individu komunitas kedua']],
