      rumus: ['S_{"Chao1"} = S_{"obs"} + \\frac{F_1^2}{2 F_2}', 'S_{"Chao1"} = S_{"obs"} + \\frac{F_1 (F_1 - 1)}{2 (F_2 + 1)}'],
      simbol: [['S_{"obs"}', 'jumlah jenis tercatat'], ['F_1', 'jumlah jenis yang hanya tercatat satu individu'], ['F_2', 'jumlah jenis yang tercatat dua individu']],
