      simbol: [['n', 'jumlah perjumpaan'], ['L', 'panjang transek'], ['r_i', 'jarak pengamat ke satwa pada perjumpaan ke-i'], ['R', 'rata-rata kebalikan jarak'], ['"var"(n)', 'ragam jumlah perjumpaan, didekati dengan n']],
      baca: 'Galat baku adalah akar ragam.',
