      rumus: ['N = 2 N_k - N_{k1}', 'N_h = \\left[ N_k + \\frac{1 - a}{a} \\right] ( N_k - N_{k1} )'],
      simbol: [['N', 'dugaan jumlah minimum populasi'], ['N_h', 'dugaan jumlah maksimum populasi'], ['N_k', 'jumlah jejak kaki terbanyak pertama'], ['N_{k1}', 'jumlah jejak kaki terbanyak kedua'], ['a', 'taraf nyata, 0,05']],
      baca: 'Contoh LPK Monitoring Rusa Doro Ncanga Mei 2022: Nk = 4 dan Nk1 = 2 menghasilkan N = 6 dan Nh = 46.',
      pakai: 'Monitoring rusa timor.',
